10	package org.elasticsearch.core;
11	
12	public final class Booleans {
13	    private Booleans() {
14	        throw new AssertionError("No instances intended");
15	    }
16	
17	    /**
18	     * Parses a char[] representation of a boolean value to <code>boolean</code>.
19	     *
20	     * @return <code>true</code> iff the sequence of chars is "true", <code>false</code> iff the sequence of chars is "false" or the
21	     * provided default value iff either text is <code>null</code> or length == 0.
22	     * @throws IllegalArgumentException if the string cannot be parsed to boolean.
23	     */
24	    public static boolean parseBoolean(char[] text, int offset, int length, boolean defaultValue) {
25	        if (text == null || length == 0) {
26	            return defaultValue;
27	        } else {
28	            return parseBoolean(new String(text, offset, length));
29	        }
30	    }
31	
32	    /**
33	     * returns true iff the sequence of chars is one of "true","false".
34	     *
35	     * @param text   sequence to check
36	     * @param offset offset to start
37	     * @param length length to check
38	     */
39	    public static boolean isBoolean(char[] text, int offset, int length) {
40	        if (text == null || length == 0) {
41	            return false;
42	        }
43	        return isBoolean(new String(text, offset, length));
44	    }
45	
46	    public static boolean isBoolean(String value) {
47	        return isFalse(value) || isTrue(value);
48	    }
49	
50	    /**
51	     * Parses a string representation of a boolean value to <code>boolean</code>.
52	     *
53	     * @return <code>true</code> iff the provided value is "true". <code>false</code> iff the provided value is "false".
54	     * @throws IllegalArgumentException if the string cannot be parsed to boolean.
55	     */
56	    public static boolean parseBoolean(String value) {
57	        if (isFalse(value)) {
58	            return false;
59	        }
60	        if (isTrue(value)) {
61	            return true;
62	        }
63	        throw new IllegalArgumentException("Failed to parse value [" + value + "] as only [true] or [false] are allowed.");
64	    }
65	
66	    private static boolean hasText(CharSequence str) {
67	        if (str == null || str.length() == 0) {
68	            return false;
69	        }
70	        int strLen = str.length();
71	        for (int i = 0; i < strLen; i++) {
72	            if (Character.isWhitespace(str.charAt(i)) == false) {
73	                return true;
74	            }
75	        }
76	        return false;
77	    }
