79	    /**
80	     *
81	     * @param value text to parse.
82	     * @param defaultValue The default value to return if the provided value is <code>null</code>.
83	     * @return see {@link #parseBoolean(String)}
84	     */
85	    public static boolean parseBoolean(String value, boolean defaultValue) {
86	        if (hasText(value)) {
87	            return parseBoolean(value);
88	        }
89	        return defaultValue;
90	    }
