12	/**
13	 * Utility class for glob-like matching
14	 */
15	public class Glob {
16	
17	    private Glob() {}
18	
19	    /**
20	     * Match a String against the given pattern, supporting the following simple
21	     * pattern styles: "xxx*", "*xxx", "*xxx*" and "xxx*yyy" matches (with an
22	     * arbitrary number of pattern parts), as well as direct equality.
23	     *
24	     * @param pattern the pattern to match against
25	     * @param str     the String to match
26	     * @return whether the String matches the given pattern
27	     */
28	    public static boolean globMatch(String pattern, String str) {
29	        if (pattern == null || str == null) {
30	            return false;
31	        }
32	
33	        int patternIndex = pattern.indexOf('*');
34	        if (patternIndex == -1) {
35	            // Nothing to glob
36	            return pattern.equals(str);
37	        }
38	
39	        if (patternIndex == 0) {
40	            // If the pattern is a literal '*' then it matches any input
41	            if (pattern.length() == 1) {
42	                return true;
43	            }
44	        } else {
45	            if (str.regionMatches(0, pattern, 0, patternIndex) == false) {
46	                // If the pattern starts with a literal (i.e. not '*') then the input string must also start with that
47	                return false;
48	            }
49	            if (patternIndex == pattern.length() - 1) {
50	                // The pattern is "something*", so if the starting region matches, then the whole pattern matches
51	                return true;
52	            }
53	        }
54	
55	        int strIndex = patternIndex;
56	        while (strIndex < str.length()) {
57	            assert pattern.charAt(patternIndex) == '*' : "Expected * at index " + patternIndex + " of [" + pattern + "]";
58	
59	            // skip over the '*'
60	            patternIndex++;
61	
62	            if (patternIndex == pattern.length()) {
63	                // The pattern ends in '*' (that is, "something*" or "*some*thing*", etc)
64	                // Since we already matched everything up to the '*' we know the string matches (whatever is left over must match '*')
65	                // so we're automatically done
66	                return true;
67	            }
68	
69	            // Look for the next '*'
70	            int nextStar = pattern.indexOf('*', patternIndex);
71	            while (nextStar == patternIndex) {
72	                // Two (or more) stars in sequence, just skip the subsequent ones
73	                patternIndex++;
74	                nextStar = pattern.indexOf('*', patternIndex);
75	            }
76	            if (nextStar == -1) {
77	                // We've come to the last '*' in a pattern (.e.g the 2nd one in "*some*thing")
78	                // In this case we match if the input string ends in "thing" (but constrained by the current position)
79	                final int len = pattern.length() - patternIndex;
80	                final int strSuffixStart = str.length() - len;
81	                if (strSuffixStart < strIndex) {
82	                    // The suffix would start before the current position. That means it's not a match
83	                    // e.g. "abc" is not a match for "ab*bc" even though "abc" does end with "bc"
84	                    return false;
85	                }
86	                return str.regionMatches(strSuffixStart, pattern, patternIndex, len);
87	            } else {
88	                // There is another star, with a literal in between the current position and that '*'
89	                // That is, we have "*literal*"
90	                // We want the first '*' to consume everything up until the first occurrence of "literal" in the input string
91	                int match = str.indexOf(pattern.substring(patternIndex, nextStar), strIndex);
92	                if (match == -1) {
93	                    // If "literal" isn't there, then the match fails.
94	                    return false;
95	                }
96	                // Move both index (pointer) values to the end of the literal
97	                strIndex = match + (nextStar - patternIndex);
98	                patternIndex = nextStar;
99	            }
100	        }
101	
102	        // We might have trailing '*'s in the pattern after completing a literal match at the end of the input string
103	        // e.g. a glob of "el*ic*" matching "elastic" - we need to consume that last '*' without it matching anything
104	        while (patternIndex < pattern.length() && pattern.charAt(patternIndex) == '*') {
105	            patternIndex++;
106	        }
107	
108	        // The match is successful only if we have consumed the entire pattern.
109	        return patternIndex == pattern.length();
110	    }
111	
112	}
