6	 * your election, the "Elastic License 2.0", the "GNU Affero General Public
7	 * License v3.0 only", or the "Server Side Public License, v 1".
8	 */
9	
10	package org.elasticsearch.dissect;
11	
12	import java.util.EnumSet;
13	import java.util.regex.Matcher;
14	import java.util.regex.Pattern;
15	
16	/**
17	 * <p>A Key of a dissect pattern. This class models the name and modifiers and provides some validation.</p>
18	 * <p>For dissect pattern of {@code %{a} %{+a} %{b}} the dissect keys are:
19	 * <ul>
20	 * <li>{@code a}</li>
21	 * <li>{@code +a}</li>
22	 * <li>{@code b}</li>
23	 * </ul>
24	 * This class represents a single key.
25	 * <p>A single key is composed of a name and it's modifiers. For the key {@code +a}, {@code a} is the name and {@code +} is the modifier.
26	 * @see DissectParser
27	 */
28	public final class DissectKey {
29	    private static final Pattern LEFT_MODIFIER_PATTERN = Pattern.compile("([+*&?])(.*?)(->)?$", Pattern.DOTALL);
30	    private static final Pattern RIGHT_PADDING_PATTERN = Pattern.compile("^(.*?)(->)?$", Pattern.DOTALL);
31	    private static final Pattern APPEND_WITH_ORDER_PATTERN = Pattern.compile("[+](.*?)(/)([0-9]+)(->)?$", Pattern.DOTALL);
32	    private final Modifier modifier;
33	    private boolean skip;
34	    private boolean skipRightPadding;
35	    private int appendPosition;
36	    private String name;
37	
38	    /**
39	     * Constructor - parses the String key into it's name and modifier(s)
40	     *
41	     * @param key The key without the leading <code>%{</code> or trailing <code>}</code>, for example {@code a->}
42	     */
43	    DissectKey(String key) {
44	        skip = key == null || key.isEmpty();
45	        modifier = Modifier.findModifier(key);
46	        switch (modifier) {
47	            case NONE:
48	                Matcher matcher = RIGHT_PADDING_PATTERN.matcher(key);
49	                while (matcher.find()) {
50	                    name = matcher.group(1);
51	                    skipRightPadding = matcher.group(2) != null;
52	                }
53	                skip = name.isEmpty();
54	                break;
55	            case NAMED_SKIP:
56	                matcher = LEFT_MODIFIER_PATTERN.matcher(key);
57	                while (matcher.find()) {
58	                    name = matcher.group(2);
59	                    skipRightPadding = matcher.group(3) != null;
60	                }
61	                skip = true;
62	                break;
63	            case APPEND:
64	                matcher = LEFT_MODIFIER_PATTERN.matcher(key);
65	                while (matcher.find()) {
66	                    name = matcher.group(2);
67	                    skipRightPadding = matcher.group(3) != null;
68	                }
69	                break;
70	            case FIELD_NAME:
71	                matcher = LEFT_MODIFIER_PATTERN.matcher(key);
72	                while (matcher.find()) {
73	                    name = matcher.group(2);
74	                    skipRightPadding = matcher.group(3) != null;
75	                }
76	                break;
77	            case FIELD_VALUE:
78	                matcher = LEFT_MODIFIER_PATTERN.matcher(key);
79	                while (matcher.find()) {
80	                    name = matcher.group(2);
81	                    skipRightPadding = matcher.group(3) != null;
82	                }
83	                break;
84	            case APPEND_WITH_ORDER:
85	                matcher = APPEND_WITH_ORDER_PATTERN.matcher(key);
86	                while (matcher.find()) {
87	                    name = matcher.group(1);
88	                    appendPosition = Short.valueOf(matcher.group(3));
89	                    skipRightPadding = matcher.group(4) != null;
90	                }
91	                break;
92	        }
93	
94	        if (name == null || (name.isEmpty() && skip == false)) {
95	            throw new DissectException.KeyParse(key, "The key name could not be determined");
96	        }
97	    }
98	
99	    /**
100	     * Copy constructor to explicitly override the modifier.
101	     * @param key The key to copy (except for the modifier)
102	     * @param modifier the modifier to use for this copy
103	     */
104	    DissectKey(DissectKey key, DissectKey.Modifier modifier) {
105	        this.modifier = modifier;
106	        this.skipRightPadding = key.skipRightPadding;
107	        this.skip = key.skip;
108	        this.name = key.name;
109	        this.appendPosition = key.appendPosition;
110	    }
111	
112	    Modifier getModifier() {
113	        return modifier;
114	    }
115	
116	    boolean skip() {
117	        return skip;
118	    }
119	
120	    boolean skipRightPadding() {
121	        return skipRightPadding;
122	    }
123	
124	    int getAppendPosition() {
125	        return appendPosition;
126	    }
127	
128	    String getName() {
129	        return name;
130	    }
131	
132	    // generated
133	    @Override
134	    public String toString() {
135	        return "DissectKey{"
136	            + "modifier="
137	            + modifier
138	            + ", skip="
139	            + skip
140	            + ", appendPosition="
141	            + appendPosition
142	            + ", name='"
143	            + name
144	            + '\''
145	            + '}';
146	    }
147	
148	    public enum Modifier {
149	        NONE(""),
150	        APPEND_WITH_ORDER("/"),
151	        APPEND("+"),
152	        FIELD_NAME("*"),
153	        FIELD_VALUE("&"),
154	        NAMED_SKIP("?");
155	
156	        private static final Pattern MODIFIER_PATTERN = Pattern.compile("[/+*&?]");
157	
158	        private final String modifier;
159	
160	        @Override
161	        public String toString() {
162	            return modifier;
163	        }
164	
165	        Modifier(final String modifier) {
166	            this.modifier = modifier;
167	        }
168	
169	        // package private for testing
170	        static Modifier fromString(String modifier) {
171	            return EnumSet.allOf(Modifier.class)
172	                .stream()
173	                .filter(km -> km.modifier.equals(modifier))
174	                .findFirst()
175	                .orElseThrow(() -> new IllegalArgumentException("Found invalid modifier.")); // throw should never happen
176	        }
177	
178	        private static Modifier findModifier(String key) {
179	            Modifier modifier = Modifier.NONE;
180	            if (key != null && key.isEmpty() == false) {
181	                Matcher matcher = MODIFIER_PATTERN.matcher(key);
182	                int matches = 0;
183	                while (matcher.find()) {
184	                    Modifier priorModifier = modifier;
185	                    modifier = Modifier.fromString(matcher.group());
186	                    if (++matches > 1 && (APPEND.equals(priorModifier) && APPEND_WITH_ORDER.equals(modifier)) == false) {
187	                        throw new DissectException.KeyParse(key, "multiple modifiers are not allowed.");
188	                    }
189	                }
190	            }
191	            return modifier;
192	        }
193	    }
194	}
