35	class MemorySegmentUtils {
36	
37	    private static final Logger log = LogManager.getLogger(MemorySegmentUtils.class);
38	
39	    /**
40	     * Encapsulates a {@link MemorySegment} in a closeable interface; when the MemorySegment is no longer used,
41	     * call {@link Closeable#close()} to release all the resources associated with the {@link MemorySegment}.
42	     */
43	    public interface MemorySegmentHolder extends Closeable {
44	        MemorySegment memorySegment();
45	
46	        @Override
47	        default void close() {}
48	    }
49	
50	    private MemorySegmentUtils() {}
51	
52	    /**
53	     * Unwraps a {@link Directory} through any {@link FilterDirectory} layers to find the underlying {@link FSDirectory}.
54	     * Elasticsearch wraps directories (e.g. {@code Store$StoreDirectory} extends {@code FilterDirectory}), so a direct
55	     * cast to {@link FSDirectory} will fail at runtime.
56	     *
57	     * @throws IllegalArgumentException if the unwrapped directory is not an {@link FSDirectory}
58	     */
59	    static FSDirectory unwrapFSDirectory(Directory dir) {
60	        Directory unwrapped = FilterDirectory.unwrap(dir);
61	        if (unwrapped instanceof FSDirectory fsDir) {
62	            return fsDir;
63	        }
64	        throw new IllegalArgumentException(
65	            "expected an FSDirectory but got [" + unwrapped.getClass().getName() + "] after unwrapping [" + dir.getClass().getName() + "]"
66	        );
67	    }
68	
69	    /**
70	     * Creates a file-backed MemorySegment, mapping the first {@param dataSize} bytes from {@param dataFile}, using the
71	     * Java {@link FileChannel} API.
72	     */
73	    static MemorySegmentHolder createFileBackedMemorySegment(Path dataFile, long dataSize) throws IOException {
74	        // Unwrap test-only filesystem layers so we get a real FileChannelImpl that supports Arena-based map.
75	        Path unwrappedPath = Unwrappable.unwrapAll(dataFile);
76	        Arena arena = null;
77	        try {
78	            arena = Arena.ofConfined();
79	            try (FileChannel fc = FileChannel.open(unwrappedPath, Set.of(READ))) {
80	                MemorySegment mapped = fc.map(FileChannel.MapMode.READ_ONLY, 0L, dataSize, arena);
81	                return new FileBackedMemorySegmentHolder(mapped, arena, dataFile);
82	            }
83	        } catch (Throwable t) {
84	            if (arena != null) {
85	                arena.close();
86	            }
87	            IOUtils.deleteFilesIgnoringExceptions(dataFile);
88	            throw t;
89	        }
90	    }
91	
92	    /**
93	     * This method returns a contiguous {@link MemorySegment} over the whole vector data.
94	     * <p>
95	     * Native methods accepting a single memory pointer (e.g. cuVS functions) expect all data to be accessible as a contiguous block.
96	     * This method tries to get a {@link MemorySegment} slice for the whole {@link IndexInput}. If the input
97	     * is larger than {@link MMapDirectory#getMaxChunkSize()} (default {@link MMapDirectory#DEFAULT_MAX_CHUNK_SIZE}),
98	     * this fails, as {@link MMapDirectory} divides it into multiple {@link MemorySegment}s.
99	     * In this case, the method falls back to creating a file-backed {@link MemorySegment} over the whole vector data.
100	     * The file-backed MemorySegment is created by copying all the vector data to a temporary file, then manually mapping the whole  file
101	     * via the Java {@link FileChannel} API.
102	     */
103	    public static MemorySegmentHolder getContiguousMemorySegment(MemorySegmentAccessInput input, Directory dir, String baseName)
104	        throws IOException {
105	        var inputSlice = input.segmentSliceOrNull(0L, input.length());
106	        if (inputSlice != null) {
107	            return new DirectMemorySegmentHolder(inputSlice);
108	        }
109	
110	        FSDirectory fsDir = unwrapFSDirectory(dir);
111	
112	        log.info(
113	            "Unable to get a contiguous memory segment for [{}, size [{}]]. Falling back to manual mapping a temp copy.",
114	            baseName,
115	            input.length()
116	        );
117	        Path tempVectorsFilePath = copyInputToTempFile((IndexInput) input, fsDir, baseName);
118	        return createFileBackedMemorySegment(tempVectorsFilePath, input.length());
119	    }
120	
121	    /**
122	     * This method returns a contiguous {@link MemorySegment} over the whole vector data.
123	     * <p>
124	     * Native methods accepting a single memory pointer (e.g. cuVS functions) expect all data to be accessible as a contiguous block;
125	     * however some vector formats add padding and/or extra data (e.g. corrections) after the vector values.
126	     * Before passing a {@link MemorySegment}/memory pointer to these data, we need to compact them.
127	     * This method employs a similar schema to {@link MemorySegmentUtils#getContiguousMemorySegment}, using a single MemorySegment from
128	     * the input {@link MemorySegmentAccessInput} when possible, and falling back to a file-backed {@link MemorySegment} when the
129	     * input data is too large.
130	     */
131	    public static MemorySegmentHolder getContiguousPackedMemorySegment(
132	        MemorySegmentAccessInput input,
133	        Directory dir,
134	        String baseName,
135	        int numVectors,
136	        int sourceRowPitch,
137	        int packedRowSize
138	    ) throws IOException {
139	        long packedVectorsDataSize = (long) numVectors * packedRowSize;
140	        MemorySegment sourceSegment = input.segmentSliceOrNull(0, input.length());
141	        if (sourceSegment != null) {
142	            Arena arena = null;
143	            try {
144	                arena = Arena.ofConfined();
145	                var packedSegment = arena.allocate(packedVectorsDataSize, 64);
146	                for (int i = 0; i < numVectors; i++) {
147	                    MemorySegment.copy(sourceSegment, (long) i * sourceRowPitch, packedSegment, (long) i * packedRowSize, packedRowSize);
148	                }
149	                return new ArenaMemorySegmentHolder(packedSegment, arena);
150	            } catch (Throwable t) {
151	                if (arena != null) {
152	                    arena.close();
153	                }
154	                throw t;
155	            }
156	        }
157	
158	        FSDirectory fsDir = unwrapFSDirectory(dir);
159	
160	        log.info(
161	            "Unable to get a contiguous memory segment for [{}, size [{}]]. Falling back creating a packed temp copy.",
162	            baseName,
163	            input.length()
164	        );
165	        var tempVectorsFile = copyInputToTempFilePacked((IndexInput) input, fsDir, baseName, numVectors, sourceRowPitch, packedRowSize);
166	        return createFileBackedMemorySegment(tempVectorsFile, packedVectorsDataSize);
167	    }
168	
169	    static Path copyInputToTempFile(IndexInput input, FSDirectory dir, String baseName) throws IOException {
170	        try (
171	            IndexInput clonedInput = input.clone();
172	            IndexOutput tempVectorsFile = dir.createTempOutput(baseName, "vec_", IOContext.DEFAULT)
173	        ) {
174	            clonedInput.seek(0);
175	            tempVectorsFile.copyBytes(clonedInput, clonedInput.length());
176	            return dir.getDirectory().resolve(tempVectorsFile.getName());
177	        }
178	    }
179	
180	    /**
181	     * Copies {@param input} vector data to a temporary file, packing the vectors to remove any padding at the end of the vector data.
182	     * @param input             the file holding the vector data
183	     * @param dir               the Lucene data directory
184	     * @param baseName          the input name
185	     * @param numVectors        the number of vectors in the input file
186	     * @param sourceRowPitch    the distance (in bytes) between 2 vectors in the input file, extra data/padding included
187	     * @param packedRowSize     the size (in bytes) of a single vector
188	     * @return the absolute path of the newly created temp file.
189	     */
190	    static Path copyInputToTempFilePacked(
191	        IndexInput input,
192	        FSDirectory dir,
193	        String baseName,
194	        int numVectors,
195	        int sourceRowPitch,
196	        int packedRowSize
197	    ) throws IOException {
198	        try (
199	            IndexInput clonedInput = input.clone();
200	            IndexOutput tempVectorsFile = dir.createTempOutput(baseName, "vec_", IOContext.DEFAULT)
201	        ) {
202	
203	            byte[] buffer = new byte[packedRowSize];
204	            for (int i = 0; i < numVectors; i++) {
205	                clonedInput.seek((long) i * sourceRowPitch);
206	                clonedInput.readBytes(buffer, 0, packedRowSize);
207	                tempVectorsFile.writeBytes(buffer, 0, packedRowSize);
208	            }
209	
210	            return dir.getDirectory().resolve(tempVectorsFile.getName());
211	        }
212	    }
213	
214	    record FileBackedMemorySegmentHolder(MemorySegment memorySegment, Arena arena, Path dataFile) implements MemorySegmentHolder {
215	        @Override
216	        public void close() {
217	            arena.close();
218	            IOUtils.deleteFilesIgnoringExceptions(dataFile);
219	        }
220	    }
221	
222	    record ArenaMemorySegmentHolder(MemorySegment memorySegment, Arena arena) implements MemorySegmentHolder {
223	        @Override
224	        public void close() {
225	            arena.close();
226	        }
227	    }
228	
229	    record DirectMemorySegmentHolder(MemorySegment memorySegment) implements MemorySegmentHolder {}
230	}
