45	    public enum MatchType {
46	        /**
47	         * DEFAULT is set when the user did not explicitly set a match_pattern in their dynamic_templates entry.
48	         * DEFAULT uses the functionality of SIMPLE for matching, but does additional validation
49	         * to detect whether the user appears to be using regex notation, in order to provide a warning.
50	         */
51	        DEFAULT {
52	            @Override
53	            public boolean matches(String pattern, String value) {
54	                return MatchType.SIMPLE.matches(pattern, value);
55	            }
56	
57	            @Override
58	            public String toString() {
59	                return "default";
60	            }
61	
62	            /**
63	             * Attempts to determine if the String passed in appears to be
64	             * regular expression rather than a simple wildcard match or a
65	             * regular ES field name (or dotted path) with no regex metacharacters.
66	             *
67	             * The method looks for the presence of standard regex metacharacters
68	             * like $, ^, |, .*, or paired braces or brackets. If found, it will then
69	             * attempt to compile it as a regex to determine if it is a valid regex.
70	             *
71	             * It will add a {@link HeaderWarning} if the user appears to be passing in a regex
72	             * in a default (simple) match scenario. This method will not throw an Exception.
73	             *
74	             * @param pattern pattern to evaluate
75	             */
76	            @Override
77	            public void validate(String pattern, String templateName) {
78	                // regexes cannot start with '*' so we assume this is valid (not a regex)
79	                if (pattern.startsWith("*")) {
80	                    return;
81	                }
82	
83	                boolean regexCandidate = false;
84	                if (pattern.startsWith(".*")) {  // .* is valid for SIMPLE because of ES dotted field names, except at string start
85	                    regexCandidate = true;
86	                } else if (pattern.contains("^")) {
87	                    regexCandidate = true;
88	                } else if (pattern.contains("$")) {
89	                    regexCandidate = true;
90	                } else if (pattern.contains("|")) {
91	                    regexCandidate = true;
92	                } else if (pattern.contains("[") && pattern.contains("]")) {
93	                    regexCandidate = true;
94	                } else if (pattern.contains("{") && pattern.contains("}")) {
95	                    regexCandidate = true;
96	                }
97	
98	                if (regexCandidate) {
99	                    try {
100	                        Pattern.compile(pattern);
101	                        // simple patterns only warrant a warning and only if the user did not explicitly set match_pattern=simple
102	                        String warning = "Pattern ["
103	                            + pattern
104	                            + "] in dynamic template ["
105	                            + templateName
106	                            + "] appears to be a regular expression, not a simple wildcard pattern"
107	                            + ". To remove this warning, set [match_pattern] in the dynamic template.";
108	                        HeaderWarning.addWarning(warning);
109	                    } catch (PatternSyntaxException e) {
110	                        // ignore since it is not a valid regex
111	                    }
112	                }
113	            }
114	        },
115	        SIMPLE {
116	            @Override
117	            public boolean matches(String pattern, String value) {
118	                return Regex.simpleMatch(pattern, value);
119	            }
120	
121	            @Override
122	            public String toString() {
123	                return "simple";
124	            }
125	
126	            @Override
127	            public void validate(String pattern, String templateName) {
128	                // no-op. All patterns are valid if user explicitly set match_pattern=simple
129	            }
130	        },
131	        REGEX {
132	            @Override
133	            public boolean matches(String pattern, String value) {
134	                return value.matches(pattern);
135	            }
136	
137	            @Override
138	            public String toString() {
139	                return "regex";
140	            }
141	
142	            /**
143	             * If pattern is valid, no exception is thrown.
144	             * @param pattern to evaluate
145	             * @throws MapperParsingException if pattern is not a valid Java regex
146	             */
147	            @Override
148	            public void validate(String pattern, String templateName) {
149	                try {
150	                    // if it parses as a Java regex, it is valid
151	                    this.matches(pattern, "");
152	                } catch (PatternSyntaxException e) {
153	                    // fail dynamic_template calls that have invalid regexes
154	                    throw new MapperParsingException(
155	                        Strings.format(
156	                            "Pattern [%s] of type [regex] is invalid. Cannot create dynamic template [%s].",
157	                            pattern,
158	                            templateName
159	                        ),
160	                        e
161	                    );
162	                }
163	            }
164	        };
165	
166	        public static MatchType fromString(String value) {
167	            for (MatchType v : values()) {
168	                if (v.toString().equals(value)) {
169	                    return v;
170	                }
171	            }
172	            throw new IllegalArgumentException("No matching pattern matched on [" + value + "]");
173	        }
174	
175	        /** Whether {@code value} matches {@code regex}. */
176	        public abstract boolean matches(String regex, String value);
177	
178	        /**
179	         * Validates {@code pattern} for the MatchType.
180	         * @param pattern to validate
181	         * @param templateName naming of the dynamic_template passed in (for use in warnings/error messages)
182	         * @throws IllegalArgumentException if the pattern is not valid
183	         */
184	        public abstract void validate(String pattern, String templateName);
185	    }
