266	    @SuppressWarnings("unchecked")
267	    static DynamicTemplate parse(String name, Map<String, ?> conf) throws MapperParsingException {
268	        List<String> match = new ArrayList<>(4); // these pattern lists will typically be very small
269	        List<String> pathMatch = new ArrayList<>(4);
270	        List<String> unmatch = new ArrayList<>(4);
271	        List<String> pathUnmatch = new ArrayList<>(4);
272	        Map<String, Object> mapping = null;
273	        boolean runtime = false;
274	        List<String> matchMappingType = new ArrayList<>(4);
275	        List<String> unmatchMappingType = new ArrayList<>(4);
276	        String matchPattern = MatchType.DEFAULT.toString();
277	
278	        for (Map.Entry<String, ?> entry : conf.entrySet()) {
279	            String propName = entry.getKey();
280	            if ("match".equals(propName)) {
281	                addEntriesToPatternList(match, propName, entry);
282	            } else if ("path_match".equals(propName)) {
283	                addEntriesToPatternList(pathMatch, propName, entry);
284	            } else if ("unmatch".equals(propName)) {
285	                addEntriesToPatternList(unmatch, propName, entry);
286	            } else if ("path_unmatch".equals(propName)) {
287	                addEntriesToPatternList(pathUnmatch, propName, entry);
288	            } else if ("match_mapping_type".equals(propName)) {
289	                addEntriesToPatternList(matchMappingType, propName, entry);
290	            } else if ("unmatch_mapping_type".equals(propName)) {
291	                addEntriesToPatternList(unmatchMappingType, propName, entry);
292	            } else if ("match_pattern".equals(propName)) {
293	                matchPattern = entry.getValue().toString();
294	            } else if ("mapping".equals(propName)) {
295	                if (mapping != null) {
296	                    throw new MapperParsingException(
297	                        "mapping and runtime cannot be both specified in the same dynamic template [" + name + "]"
298	                    );
299	                }
300	                mapping = (Map<String, Object>) entry.getValue();
301	                runtime = false;
302	            } else if ("runtime".equals(propName)) {
303	                if (mapping != null) {
304	                    throw new MapperParsingException(
305	                        "mapping and runtime cannot be both specified in the same dynamic template [" + name + "]"
306	                    );
307	
308	                }
309	                mapping = (Map<String, Object>) entry.getValue();
310	                runtime = true;
311	            } else {
312	                // unknown parameters were ignored before but still carried through serialization
313	                // so we need to ignore them at parsing time for old indices
314	                throw new IllegalArgumentException("Illegal dynamic template parameter: [" + propName + "]");
315	            }
316	        }
317	        if (mapping == null) {
318	            throw new MapperParsingException("template [" + name + "] must have either mapping or runtime set");
319	        }
320	
321	        // match, path_match, and unmatch_mapping_type all imply
322	        // "match_mapping_type: *" if not explicitly specified.
323	        final boolean wildcardMatchMappingType = ((matchMappingType.isEmpty()
324	            && matchPatternsAreDefined(match, pathMatch, unmatchMappingType))
325	            || (matchMappingType.size() == 1 && matchMappingType.get(0).equals("*")));
326	
327	        Stream<XContentFieldType> matchXContentFieldTypes;
328	        if (wildcardMatchMappingType) {
329	            matchXContentFieldTypes = Stream.of(XContentFieldType.values());
330	            if (runtime) {
331	                matchXContentFieldTypes = matchXContentFieldTypes.filter(XContentFieldType::supportsRuntimeField);
332	            }
333	        } else {
334	            if (runtime) {
335	                final List<String> unsupported = matchMappingType.stream()
336	                    .map(XContentFieldType::fromString)
337	                    .filter(Predicate.not(XContentFieldType::supportsRuntimeField))
338	                    .map(XContentFieldType::toString)
339	                    .toList();
340	                if (unsupported.isEmpty() == false) {
341	                    final int numUnsupported = unsupported.size();
342	                    throw new MapperParsingException(
343	                        "Dynamic template ["
344	                            + name
345	                            + "] defines a runtime field but type"
346	                            + (numUnsupported == 1 ? "" : "s")
347	                            + " ["
348	                            + String.join(", ", unsupported)
349	                            + "] "
350	                            + (numUnsupported == 1 ? "is" : "are")
351	                            + " not supported as runtime field"
352	                    );
353	                }
354	            }
355	            matchXContentFieldTypes = matchMappingType.stream().map(XContentFieldType::fromString);
356	        }
357	
358	        final Set<XContentFieldType> unmatchXContentFieldTypesSet = unmatchMappingType.stream()
359	            .map(XContentFieldType::fromString)
360	            .collect(Collectors.toSet());
361	        final XContentFieldType[] xContentFieldTypes = matchXContentFieldTypes.filter(Predicate.not(unmatchXContentFieldTypesSet::contains))
362	            .toArray(XContentFieldType[]::new);
363	
364	        final MatchType matchType = MatchType.fromString(matchPattern);
365	        // no need to check return value - the method impls either have side effects (set header warnings)
366	        // or throw an exception that should be sent back to the user
367	        Stream.of(match, unmatch, pathMatch, pathUnmatch).flatMap(Collection::stream).forEach(pattern -> matchType.validate(pattern, name));
368	        return new DynamicTemplate(
369	            name,
370	            pathMatch,
371	            pathUnmatch,
372	            match,
373	            unmatch,
374	            matchMappingType,
375	            unmatchMappingType,
376	            xContentFieldTypes,
377	            matchType,
378	            mapping,
379	            runtime
380	        );
381	    }
