383	    /**
384	     * @param matchLists zero or more lists of match patterns (can be empty but not null)
385	     * @return return true if any of the given lists is non-empty
386	     */
387	    private static boolean matchPatternsAreDefined(final List<?>... matchLists) {
388	        return Stream.of(matchLists).anyMatch(Predicate.not(List::isEmpty));
389	    }
