391	    private static void addEntriesToPatternList(List<String> matchList, String propName, Map.Entry<String, ?> entry) {
392	        if (entry.getValue() instanceof List<?> ls) {
393	            for (Object o : ls) {
394	                if (o instanceof String s) {
395	                    matchList.add(s);
396	                } else {
397	                    // for array-based matches, we enforce that only strings are allowed as un/match values in the array
398	                    throw new MapperParsingException(
399	                        Strings.format("[%s] values must either be a string or list of strings, but was [%s]", propName, entry.getValue())
400	                    );

