307	     * Validate that child settings are valid
308	     */
309	    public static void validateSettings(BreakerSettings[] childrenSettings) throws IllegalStateException {
310	        for (BreakerSettings childSettings : childrenSettings) {
311	            // If the child is disabled, ignore it
312	            if (childSettings.getLimit() == -1) {
313	                continue;
314	            }
315	
316	            if (childSettings.getOverhead() < 0) {
317	                throw new IllegalStateException("Child breaker overhead " + childSettings + " must be non-negative");
318	            }
319	        }
320	    }
