354	    static class MemoryUsage {
355	        final long baseUsage;
356	        final long totalUsage;
357	        final long transientChildUsage;
358	        final long permanentChildUsage;
359	
360	        MemoryUsage(final long baseUsage, final long totalUsage, final long transientChildUsage, final long permanentChildUsage) {
361	            this.baseUsage = baseUsage;
362	            this.totalUsage = totalUsage;
363	            this.transientChildUsage = transientChildUsage;
364	            this.permanentChildUsage = permanentChildUsage;
365	        }
366	    }
367	
368	    private MemoryUsage memoryUsed(long newBytesReserved) {
369	        long transientUsage = 0;
370	        long permanentUsage = 0;
371	
372	        for (CircuitBreaker breaker : this.breakers.values()) {
373	            long breakerUsed = (long) (breaker.getUsed() * breaker.getOverhead());
374	            if (breaker.getDurability() == CircuitBreaker.Durability.TRANSIENT) {
375	                transientUsage += breakerUsed;
376	            } else if (breaker.getDurability() == CircuitBreaker.Durability.PERMANENT) {
377	                permanentUsage += breakerUsed;
378	            }
379	        }
380	        if (this.trackRealMemoryUsage) {
381	            final long current = currentMemoryUsage();
382	            return new MemoryUsage(current, current + newBytesReserved, transientUsage, permanentUsage);
383	        } else {
384	            long parentEstimated = transientUsage + permanentUsage;
385	            return new MemoryUsage(parentEstimated, parentEstimated, transientUsage, permanentUsage);
386	        }
387	    }
